package helpdesk;
 import java.util.Map;
 import java.util.Properties;
 public final class Policy {
     public static Strategy load(Map<String, String> env, Properties jvm) {
         String selected = "HASH";
         if (env.containsKey("PII_STRATEGY")) selected = env.get("PII_STRATEGY");
         if (jvm.containsKey("pii.strategy")) selected = jvm.getProperty("pii.strategy");
         return Strategy.valueOf(selected.toUpperCase(java.util.Locale.ROOT));
     }
 }

