package helpdesk;
 import java.util.Map;
 import java.util.Properties;
 public final class Application {
     public static String boot(Map<String, String> env, Properties jvm) {
         Strategy strategy = Policy.load(env, jvm);
         return strategy.wireKey;
     }
 }
